    if (b < OPEN_ROW_BEAT) {
      // 每半拍一个满屏大字砸下：从 1.5 倍在 3 帧内压到原大，带残影、聚光闪亮和四溅墨点
      const i = Math.min(a.slam.length - 1, Math.floor(b / OPEN_SLAM_STEP));
      const lb = b - a.slam[i].at;
