import test from 'node:test';
import assert from 'node:assert/strict';
import {BEATS, BEAT_FRAMES, FPS, FRAME_COUNT, OPEN_ROW_BEAT, OPEN_SLAM_STEP, OPEN_SNAP_BEAT, PAGES, SAMPLE_RATE, SECONDS, frameState} from './timeline.js';
import {MOTTO, SCRIPT, SOURCES, allLines} from './script.js';
import {ACCENT_BEATS, synthesize} from './music.mjs';

test('90 秒、120 BPM、180 拍，每页在拍点落定', () => {
  assert.equal(FPS, 30);
  assert.equal(BEAT_FRAMES, 15);
  assert.equal(BEATS, 180);
  assert.equal(FRAME_COUNT, 2700);
  assert.equal(SECONDS, 90);
  assert.equal(PAGES.reduce((s, p) => s + p.beats, 0), BEATS);
  for (const [i, page] of PAGES.entries()) {
    assert.equal(page.land, page.beat * BEAT_FRAMES);
    assert.equal(frameState(page.land).index, i);
    assert.equal(frameState(page.land).local, 0);
    if (i > 0) assert.equal(frameState(page.land - 1).index, i - 1);
  }
  assert.throws(() => frameState(FRAME_COUNT));
});

test('每句事实和引语都有来源，来源都存在', () => {
  for (const line of allLines()) {
    if (line.kind === 'fact' || line.kind === 'quote') assert.ok(line.refs.length > 0, `缺来源：${line.text}`);
    for (const r of line.refs) assert.ok(SOURCES[r], `来源 ${r} 不存在`);
    if (line.kind === 'view') assert.equal(line.refs.length, 0);
  }
  for (const s of Object.values(SOURCES)) assert.match(s.url, /^https:\/\//);
});

test('人名、日期、职务与来源一致', () => {
  const all = allLines().map(l => l.text).join('\n');
  assert.ok(all.includes('1980.5—1982.12'));
  assert.ok(all.includes('杭州电子工业学院首任院长'));
  assert.ok(all.includes('1979年2月'));
  assert.ok(all.includes('2026年10月16日晚'));
  assert.ok(SCRIPT.y1979.age.text === '73');
  assert.ok(SCRIPT.aid.legend.text.match(/\d+/g).map(Number).reduce((a, b) => a + b) === 58);
  for (const wrong of ['1939年获', '1936年获', '病床', '绝笔', '临终', '五中全会', '头像']) assert.ok(!all.includes(wrong), `不应出现：${wrong}`);
});

test('逐字打出的行从整拍开始，打完后留够阅读时间', () => {
  for (const page of PAGES) {
    const lines = [];
    const walk = v => {
      if (Array.isArray(v)) v.forEach(walk);
      else if (v && typeof v === 'object' && 'kind' in v) lines.push(v);
      else if (v && typeof v === 'object') Object.values(v).forEach(walk);
    };
    // 右上角标是常驻的章节信息，不计入本页阅读量。年份、人名、地名、图例、科目和重复出现的八个字方块扫一眼即可。
    const {corner, legend, names, years, subjects, term, year, age, ageUnit, count, total, first, credits, places, cubes, slam, ...body} = SCRIPT[page.id];
    walk(body);
    const glance = [legend, names, years, subjects, term, year, age, ageUnit, count, total, first, credits, places, cubes, slam].flat().filter(Boolean);
    // 句子按每秒 6 字算阅读量；句子连同短标签合计不超过每秒 8.5 字。
    let chars = glance.reduce((s, l) => s + [...l.text.replace(/[\s，。、：；“”（）《》·—…]/g, '')].length, 0), sentence = 0;
    for (const l of lines) {
      if (l.kind === 'label' && /^来源|示意/.test(l.text)) continue;
      const n = [...l.text.replace(/[\s，。、：；“”（）《》·—…]/g, '')].length;
      chars += n;
      sentence += n;
      if (l.kind !== 'label' && l.at > 0 && l.text.length > 3) {
        assert.ok(Number.isInteger(l.at) || page.id === 'hire' || page.id === 'ours', `${page.id}「${l.text}」不在整拍`);
        const done = l.at + [...l.text].length * 3 / BEAT_FRAMES;
        assert.ok(done + 1.5 <= page.beats, `${page.id}「${l.text}」打完后不足 0.75 秒就翻页`);
      }
    }
    const seconds = page.beats / 2;
    assert.ok(sentence / seconds <= 6, `${page.id} 句子每秒 ${(sentence / seconds).toFixed(1)} 字，超过 6 字`);
    assert.ok(chars / seconds <= 8.5, `${page.id} 全部文字每秒 ${(chars / seconds).toFixed(1)} 字，超过 8.5 字`);
  }
});

test('不用口号和被禁的句式', () => {
  const banned = ['而是', '不是', '落地', '钉死', '对齐', '赋能', '伟大', '永远', '必将', '一定要'];
  for (const line of allLines()) for (const word of banned) assert.ok(!line.text.includes(word), `${line.text} 含 ${word}`);
});

test('开场从第 0 帧起每半拍砸下一个字，第 7 拍人名聚成', () => {
  assert.equal(PAGES[0].id, 'open');
  assert.equal(PAGES[0].beats, 12);
  assert.equal(OPEN_SNAP_BEAT, 7);
  assert.deepEqual(SCRIPT.open.slam.map(l => l.text), [...MOTTO.lines.join('')]);
  assert.equal(OPEN_SLAM_STEP * SCRIPT.open.slam.length, OPEN_ROW_BEAT);
  SCRIPT.open.slam.forEach((l, i) => {
    assert.equal(l.at, i * OPEN_SLAM_STEP);
    assert.deepEqual(l.refs, MOTTO.refs);
  });
  const {left, right} = synthesize();
  const win = Math.round(SAMPLE_RATE * 0.01);
  const energy = t => {
    const s = Math.round(t * SAMPLE_RATE);
    let e = 0;
    for (let i = s; i < s + win; i++) e += left[i] ** 2 + right[i] ** 2;
    return e;
  };
  assert.ok(energy(0) > 0.05, `第 0 帧没有重击：${energy(0)}`);
  for (const l of SCRIPT.open.slam.slice(1)) {
    const t = l.at * 0.5;
    assert.ok(energy(t) > 3 * energy(t - 0.03), `开场第 ${l.at} 拍没有重击`);
  }
});

test('配乐在每个落拍帧起音，没有削波', () => {
  const {left, right} = synthesize();
  assert.equal(left.length, SAMPLE_RATE * SECONDS);
  const win = Math.round(SAMPLE_RATE * 0.01);
  const energy = t => {
    const s = Math.round(t * SAMPLE_RATE);
    let e = 0;
    for (let i = s; i < s + win; i++) e += left[i] ** 2 + right[i] ** 2;
    return e;
  };
  for (const beat of ACCENT_BEATS) {
    const t = beat * 0.5;
    assert.ok(energy(t) > 3 * energy(t - 0.03), `第 ${beat} 拍 ${t}s 没有起音`);
  }
  for (const page of PAGES.slice(1)) assert.ok(ACCENT_BEATS.includes(page.beat));
  // 片尾和弦落在不在小节首拍的第 166 拍，淡出前每秒都要有声音。
  for (let s = 0; s + 1 <= SECONDS - 2.5; s++) {
    let e = 0;
    for (let i = s * SAMPLE_RATE; i < (s + 1) * SAMPLE_RATE; i++) e += left[i] ** 2;
    assert.ok(Math.sqrt(e / SAMPLE_RATE) > 0.01, `第 ${s} 秒没有声音`);
  }
  let peak = 0;
  for (let i = 0; i < left.length; i++) peak = Math.max(peak, Math.abs(left[i]), Math.abs(right[i]));
  assert.ok(peak < 0.9 && peak > 0.3, `峰值 ${peak}`);
});
// 输出成片：无头 Chrome 逐帧画 Canvas，ffmpeg 编码 H.264，再混入 music.mjs 合成的配乐（AAC）。
// 用法：node render.mjs                      全片
//      node render.mjs --stills 0,60,150 目录  只输出指定帧号的 PNG
//      node render.mjs --audio                 只重新合成配乐并替换成片音轨
import {spawn, spawnSync} from 'node:child_process';
import {mkdirSync, renameSync, rmSync, statSync, writeFileSync} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {openChrome} from '../../會呼吸的痛/開場樣圖/v2/chrome.mjs';
import {FPS, FRAME_COUNT, SECONDS} from './timeline.js';
import {synthesize, toWav} from './music.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const OUT_DIR = path.join(here, '输出');
const PARTS = path.join(OUT_DIR, '分段');
const WAV = path.join(OUT_DIR, '配乐.wav');
const TARGET = path.join(OUT_DIR, '八个字，一生的回答.mp4');
const WORKERS = Math.max(2, Math.min(6, os.cpus().length - 2));
const ENCODE = ['-c:v', 'libx264', '-preset', 'medium', '-crf', '17', '-threads', '2', '-g', String(FPS), '-bf', '0',
  '-vf', 'scale=out_color_matrix=bt709:out_range=tv:flags=lanczos+accurate_rnd+full_chroma_int,format=yuv420p',
  '-colorspace', 'bt709', '-color_primaries', 'bt709', '-color_trc', 'bt709', '-color_range', 'tv', '-r', String(FPS)];
const IMAGE = `document.getElementById('stage').toDataURL('image/png').split(',')[1]`;
const FRAME_TIMEOUT_MS = 60000;

// 系统睡眠唤醒后无头 Chrome 的 GPU 读回可能永远不返回，超时即终止渲染
function withTimeout(promise, n) {
  let timer;
  const timeout = new Promise((ok, fail) => { timer = setTimeout(() => fail(new Error(`第 ${n} 帧 ${FRAME_TIMEOUT_MS / 1000} 秒未返回，渲染终止`)), FRAME_TIMEOUT_MS); });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

async function renderSegment(chrome, first, count, file) {
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(FPS), '-c:v', 'png', '-i', '-', ...ENCODE, file], {stdio: ['pipe', 'inherit', 'inherit']});
  const finished = new Promise((ok, fail) => ffmpeg.once('exit', code => (code === 0 ? ok() : fail(new Error(`ffmpeg 退出 ${code}`)))));
  for (let n = first; n < first + count; n++) {
    await withTimeout(chrome.evaluate(`window.film.renderFrame(${n})`), n);
    const image = Buffer.from(await withTimeout(chrome.evaluate(IMAGE), n), 'base64');
    if (!ffmpeg.stdin.write(image)) await new Promise(ok => ffmpeg.stdin.once('drain', ok));
  }
  ffmpeg.stdin.end();
  await finished;
  const errors = await chrome.evaluate('window.renderErrors');
  if (errors.length) throw new Error(JSON.stringify(errors));
}

async function renderAll() {
  const started = Date.now();
  rmSync(PARTS, {recursive: true, force: true});
  mkdirSync(PARTS, {recursive: true});
  writeFileSync(WAV, toWav(synthesize()));
  const size = Math.ceil(FRAME_COUNT / WORKERS);
  const segments = Array.from({length: WORKERS}, (_, i) => ({first: i * size, count: Math.min(size, FRAME_COUNT - i * size), file: path.join(PARTS, `part-${i}.mp4`)}));
  await Promise.all(segments.map(async s => {
    const chrome = await openChrome();
    try {
      await chrome.openStyle('film', here);
      await renderSegment(chrome, s.first, s.count, s.file);
    } finally {
      await chrome.close();
    }
  }));
  const list = path.join(PARTS, 'list.txt');
  writeFileSync(list, segments.map(s => `file '${path.basename(s.file)}'`).join('\n') + '\n');
  const mux = spawnSync('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'concat', '-safe', '0', '-i', list, '-i', WAV,
    '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '256k', '-ar', '48000',
    '-map_metadata', '-1', '-movflags', '+faststart', '-t', String(SECONDS), TARGET], {stdio: 'inherit'});
  if (mux.status !== 0) throw new Error(`拼接失败 ${mux.status}`);
  rmSync(PARTS, {recursive: true, force: true});
  const result = {frames: FRAME_COUNT, fps: FPS, workers: WORKERS, megabytes: Number((statSync(TARGET).size / 1048576).toFixed(1)), seconds: Math.round((Date.now() - started) / 1000)};
  writeFileSync(path.join(OUT_DIR, '渲染结果.json'), JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify(result));
}

async function renderStills(frames, dir) {
  mkdirSync(dir, {recursive: true});
  const chrome = await openChrome();
  try {
    await chrome.openStyle('film', here);
    for (const n of frames) {
      await chrome.evaluate(`window.film.renderFrame(${n})`);
      writeFileSync(path.join(dir, `f${String(n).padStart(4, '0')}.png`), Buffer.from(await chrome.evaluate(IMAGE), 'base64'));
    }
    const errors = await chrome.evaluate('window.renderErrors');
    if (errors.length) throw new Error(JSON.stringify(errors));
  } finally {
    await chrome.close();
  }
}

// 只改配乐时：重新合成 WAV，复制成片的视频流，换上新的 AAC 音轨。
function remuxAudio() {
  writeFileSync(WAV, toWav(synthesize()));
  const tmp = path.join(OUT_DIR, '换音轨.mp4');
  const mux = spawnSync('ffmpeg', ['-y', '-loglevel', 'error', '-i', TARGET, '-i', WAV, '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy',
    '-c:a', 'aac', '-b:a', '256k', '-ar', '48000', '-map_metadata', '-1', '-movflags', '+faststart', '-t', String(SECONDS), tmp], {stdio: 'inherit'});
  if (mux.status !== 0) throw new Error(`换音轨失败 ${mux.status}`);
  renameSync(tmp, TARGET);
}

const args = process.argv.slice(2);
mkdirSync(OUT_DIR, {recursive: true});
if (args[0] === '--stills') await renderStills(args[1].split(',').map(Number), path.resolve(args[2]));
else if (args[0] === '--audio') remuxAudio();
else await renderAll();
// 配乐全部由代码合成：120 BPM，A 小调 Am–F–C–G 循环，结尾停在 C。
// 每次翻页的落拍帧上有底鼓、纸声和钟声组成的重音；段落密度随画面明暗变化。
// 用法：node music.mjs 输出路径.wav
import {writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {BEATS, BPM, CREED_SNAP_BEAT, OPEN_BURST_BEAT, OPEN_ROW_BEAT, OPEN_SLAM_STEP, OPEN_SNAP_BEAT, PAGES, SAMPLE_RATE as SR, SECONDS} from './timeline.js';

const BEAT = 60 / BPM;
const N = SR * SECONDS;
const midi = m => 440 * 2 ** ((m - 69) / 12);
const CHORDS = [[45, 48, 52], [41, 45, 48], [48, 52, 55], [43, 47, 50]];
const FINAL = [48, 52, 55];
const FINAL_BEAT = PAGES.find(p => p.id === 'end').beat;
const chordAt = beat => (beat >= FINAL_BEAT ? FINAL : CHORDS[Math.floor(beat / 4) % 4]);
const pageAt = beat => PAGES.findLast(p => beat >= p.beat);

// 每页的配器：pad 铺底，keys 钢琴分解和弦，pluck 八分音符拨弦，bass 低音，kick/hat 鼓。
const ARR = {
  open: {pad: 1, keys: 1},
  motto: {pad: 1, keys: 1, bass: 0.6, kick: 0.4},
  newark: {pad: 0.8, pluck: 1, bass: 1, kick: 0.5},
  plan: {pad: 0.8, pluck: 1, bass: 1, kick: 0.6, hat: 0.6},
  hire: {pad: 0.8, pluck: 1, bass: 1, kick: 0.6, hat: 0.8},
  y1979: {pad: 1, bass: 1.2, pulse: 1, kick: 0.5},
  aid: {pad: 0.8, pluck: 1.1, bass: 1, kick: 0.8, hat: 1},
  exam: {pad: 0.8, pluck: 1.1, bass: 1, kick: 0.8, hat: 1},
  creed: {pad: 0.7, keys: 0.7},
  notice: {pad: 0.8, pluck: 1.1, high: 1, bass: 1, kick: 0.8, hat: 1},
  drones: {pad: 1, pluck: 1, high: 1.2, bass: 1.1, kick: 0.9, hat: 1},
  ours: {pad: 0.8, keys: 0.9, bass: 0.8, kick: 0.4},
  end: {pad: 1.2, keys: 0.5},
};

function rng(seed) {
  return () => {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296 * 2 - 1;
  };
}

function addPluck(out, t0, freq, gain, decay = 0.996) {
  const noise = rng(Math.round(freq * 1000 + t0 * 7));
  const period = Math.round(SR / freq);
  const ring = Float32Array.from({length: period}, () => noise());
  // 激励先做两遍环形平滑，去掉白噪声起音的刺耳高频和采样跳变。
  for (let pass = 0; pass < 2; pass++) {
    const copy = Float32Array.from(ring);
    for (let k = 0; k < period; k++) ring[k] = (copy[(k + period - 1) % period] + 2 * copy[k] + copy[(k + 1) % period]) / 4;
  }
  const start = Math.round(t0 * SR);
  const len = Math.min(Math.round(SR * 1.4), N - start);
  let prev = 0;
  for (let i = 0; i < len; i++) {
    const k = i % period;
    const v = ring[k];
    ring[k] = decay * 0.5 * (v + prev);
    prev = v;
    out[start + i] += v * gain * Math.min(1, i / 48);
  }
}

function addTone(out, t0, dur, partials, attack, tau) {
  const start = Math.round(t0 * SR);
  const len = Math.min(Math.round(dur * SR), N - start);
  for (let i = 0; i < len; i++) {
    const t = i / SR;
    const env = Math.min(1, t / attack) * Math.exp(-t / tau) * Math.min(1, (len - i) / (SR * 0.03));
    let v = 0;
    for (const [f, a] of partials) v += a * Math.sin(2 * Math.PI * f * t);
    out[start + i] += v * env;
  }
}

function addKick(out, t0, gain) {
  const start = Math.round(t0 * SR);
  let phase = 0;
  for (let i = 0; i < SR * 0.4 && start + i < N; i++) {
    const t = i / SR;
    phase += 2 * Math.PI * (44 + 80 * Math.exp(-t / 0.03)) / SR;
    out[start + i] += gain * Math.sin(phase) * Math.exp(-t / 0.12);
  }
}

function addNoise(out, t0, dur, gain, shape, seed, cutoff) {
  const noise = rng(seed);
  const start = Math.round(t0 * SR);
  const a = Math.exp(-2 * Math.PI * cutoff / SR);
  let low = 0;
  for (let i = 0; i < dur * SR && start + i < N; i++) {
    low = (1 - a) * noise() + a * low;
    out[start + i] += gain * low * shape(i / (dur * SR));
  }
}

function addHat(out, t0, gain) {
  const noise = rng(Math.round(t0 * 1000));
  const start = Math.round(t0 * SR);
  let last = 0;
  for (let i = 0; i < SR * 0.05 && start + i < N; i++) {
    const n = noise();
    out[start + i] += gain * (n - last) * Math.exp(-i / (SR * 0.011));
    last = n;
  }
}

function reverb(input) {
  const outBuf = new Float32Array(N);
  for (const [ms, fb] of [[29.7, 0.8], [37.1, 0.78], [41.1, 0.76], [43.7, 0.74]]) {
    const d = Math.round(ms * SR / 1000);
    const buf = new Float32Array(N);
    for (let i = 0; i < N; i++) {
      buf[i] = input[i] + (i >= d ? buf[i - d] * fb : 0);
      outBuf[i] += buf[i] * 0.25;
    }
  }
  return outBuf;
}

// 开场：八个字每半拍一记低频重击，“尽”“力”加钟声；第 4 拍收成一行、第 5 拍炸开各一记大重击，
// 之后噪声上扬推到第 7 拍人名聚成。上扬在重音前 60 ms 停住，让重音起音清楚。
function coldOpen(dry, wet) {
  addTone(dry, 0, OPEN_SNAP_BEAT * BEAT + 0.05, [[midi(33), 0.05], [midi(40), 0.022]], 0.004, 100);
  for (let i = 0; i * OPEN_SLAM_STEP < OPEN_ROW_BEAT; i++) {
    const t = i * OPEN_SLAM_STEP * BEAT;
    const key = i >= 6;
    addKick(dry, t, key ? 0.6 : 0.5);
    addTone(dry, t, 0.5, [[midi(33), 0.2], [midi(45), 0.05]], 0.002, 0.11);
    addNoise(dry, t, 0.08, key ? 0.7 : 0.55, x => Math.exp(-x * 5), 300 + i, 2400);
    if (key) addTone(wet, t, 1.6, [[midi(81), 0.09], [midi(81) * 2.76, 0.025]], 0.002, 0.45);
  }
  for (const [beat, wash] of [[OPEN_ROW_BEAT, 0.4], [OPEN_BURST_BEAT, 1.4]]) {
    const t = beat * BEAT;
    addKick(dry, t, 0.66);
    addTone(dry, t, 1.2, [[midi(33), 0.22], [midi(21), 0.12]], 0.002, 0.3);
    addNoise(dry, t, wash, 0.36, x => Math.exp(-x * 4), 400 + beat, 3500);
    addTone(wet, t, 2, [[midi(69), 0.1], [midi(69) * 2.76, 0.03], [midi(69) * 5.4, 0.01]], 0.002, 0.6);
  }
  const riseStart = OPEN_BURST_BEAT * BEAT + 0.35, riseEnd = OPEN_SNAP_BEAT * BEAT - 0.06;
  addNoise(dry, riseStart, riseEnd - riseStart, 0.22, x => x ** 2.5, 450, 5000);
}

// 落拍的重音：页面翻转、开场八个字聚成实字、第九页八个字重新聚成。
export const ACCENT_BEATS = [...PAGES.slice(1).map(p => p.beat), OPEN_SNAP_BEAT, PAGES.find(p => p.id === 'creed').beat + CREED_SNAP_BEAT].sort((a, b) => a - b);

export function synthesize() {
  const dry = new Float32Array(N), wet = new Float32Array(N);
  const panL = new Float32Array(N), panR = new Float32Array(N);

  coldOpen(dry, wet);

  for (let beat = 0; beat < BEATS; beat++) {
    const t = beat * BEAT;
    const chord = chordAt(beat);
    const arr = ARR[pageAt(beat).id];
    // 开场重击段不铺和声，人名聚成那一拍起才进钢琴。
    if (beat < OPEN_SNAP_BEAT) continue;
    const bar = beat % 4;
    // 结尾和弦落在片尾页的第一拍（不一定是小节首拍），之前的铺底在它起音时让开。
    if (arr.pad && ((bar === 0 && beat < FINAL_BEAT) || beat === FINAL_BEAT)) {
      const final = beat === FINAL_BEAT;
      const dur = final ? SECONDS - t : Math.min(BEAT * 4, (FINAL_BEAT - beat) * BEAT) + 0.4;
      for (const m of chord) {
        addTone(dry, t, dur, [[midi(m), 0.016 * arr.pad], [midi(m) * 1.004, 0.011 * arr.pad], [midi(m + 12), 0.005 * arr.pad]], 0.5, final ? 6 : 3.2);
      }
    }
    if (arr.keys) {
      const notes = [chord[0] + 12, chord[1] + 12, chord[2] + 12, chord[1] + 24];
      const m = notes[bar];
      addTone(dry, t, 1.6, [[midi(m), 0.05 * arr.keys], [midi(m) * 2, 0.012 * arr.keys], [midi(m) * 3, 0.004 * arr.keys]], 0.004, 0.55);
      addTone(wet, t, 1.6, [[midi(m), 0.03 * arr.keys]], 0.004, 0.55);
    }
    if (arr.pluck) {
      const pattern = [chord[0] + 12, chord[2] + 12, chord[1] + 24, chord[2] + 12];
      for (const half of [0, 1]) {
        const k = bar * 2 + half;
        const target = k % 2 ? panR : panL;
        addPluck(target, t + half * BEAT / 2, midi(pattern[k % 4]), 0.12 * arr.pluck);
        addPluck(wet, t + half * BEAT / 2, midi(pattern[k % 4]), 0.035 * arr.pluck);
      }
    }
    if (arr.high) {
      const m = [chord[0] + 36, chord[2] + 24, chord[1] + 36, chord[2] + 24][bar];
      addTone(wet, t + BEAT / 2, 0.8, [[midi(m), 0.02 * arr.high]], 0.003, 0.25);
    }
    if (arr.bass) addTone(dry, t, BEAT * 0.92, [[midi(chord[0] - 12), 0.2 * arr.bass], [midi(chord[0]), 0.04 * arr.bass]], 0.008, 0.38);
    if (arr.pulse) addTone(dry, t + BEAT / 2, BEAT * 0.45, [[midi(chord[0] - 12), 0.12], [midi(chord[0] - 24), 0.08]], 0.006, 0.12);
    if (arr.kick && bar % 2 === 0) addKick(dry, t, 0.42 * arr.kick);
    if (arr.hat) addHat(dry, t + BEAT / 2, 0.07 * arr.hat);
  }

  // 翻页：落拍前 0.4 秒纸声渐起，落拍时纸页落下、底鼓与钟声同时起音。
  for (const [i, beat] of ACCENT_BEATS.entries()) {
    const t = beat * BEAT;
    const turn = PAGES.some(p => p.beat === beat);
    if (turn) addNoise(dry, t - 0.4, 0.38, 0.1, x => Math.sin(Math.PI * Math.min(1, x)) ** 2 * x, 900 + i, 3800);
    addNoise(dry, t, 0.07, 0.8, x => Math.exp(-x * 6), 100 + i, 1100);
    addKick(dry, t, 0.62);
    const root = chordAt(beat)[0] + 36;
    addTone(wet, t, 2, [[midi(root), 0.11], [midi(root) * 2.76, 0.03], [midi(root) * 5.4, 0.01]], 0.002, 0.5);
    addTone(dry, t, 1.6, [[midi(root), 0.08], [midi(root) * 2.01, 0.02]], 0.002, 0.4);
  }

  const verb = reverb(wet);
  const left = new Float32Array(N), right = new Float32Array(N);
  let peak = 0;
  for (let i = 0; i < N; i++) {
    const fade = Math.min(1, (N - i) / (SR * 2.5), i / (SR * 0.01));
    left[i] = (dry[i] + panL[i] + 0.5 * panR[i] + verb[i]) * fade;
    right[i] = (dry[i] + panR[i] + 0.5 * panL[i] + verb[i] * 0.95) * fade;
    peak = Math.max(peak, Math.abs(left[i]), Math.abs(right[i]));
  }
  // 软限幅压住重音的瞬时峰值；AAC 编码后真峰值会比 WAV 高约 2 dB，输出峰值留到约 -3.2 dBFS。
  const drive = 2.9, norm = 0.69 / Math.tanh(drive);
  for (let i = 0; i < N; i++) {
    left[i] = Math.tanh(drive * left[i] / peak) * norm;
    right[i] = Math.tanh(drive * right[i] / peak) * norm;
  }
  return {left, right};
}

export function toWav({left, right}) {
  const data = Buffer.alloc(N * 4);
  for (let i = 0; i < N; i++) {
    data.writeInt16LE(Math.round(Math.max(-1, Math.min(1, left[i])) * 32767), i * 4);
    data.writeInt16LE(Math.round(Math.max(-1, Math.min(1, right[i])) * 32767), i * 4 + 2);
  }
  const head = Buffer.alloc(44);
  head.write('RIFF', 0); head.writeUInt32LE(36 + data.length, 4); head.write('WAVE', 8);
  head.write('fmt ', 12); head.writeUInt32LE(16, 16); head.writeUInt16LE(1, 20); head.writeUInt16LE(2, 22);
  head.writeUInt32LE(SR, 24); head.writeUInt32LE(SR * 4, 28); head.writeUInt16LE(4, 32); head.writeUInt16LE(16, 34);
  head.write('data', 36); head.writeUInt32LE(data.length, 40);
  return Buffer.concat([head, data]);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) writeFileSync(process.argv[2], toWav(synthesize()));

