  // 墨迹沿晶格流开：一段缓慢起伏的低通噪声，停在第一个字显影前
  addNoise(dry, OPEN_DROP_BEAT * BEAT + 0.4, (OPEN_REVEAL_BEAT - OPEN_DROP_BEAT) * BEAT - 0.46, 0.12, x => Math.sin(Math.PI * x) ** 2, 420, 1200);
