      const burst = out(seg(b, OPEN_BURST_BEAT, OPEN_BURST_BEAT + 1));
      flash(g, 0.35 * (1 - seg(b, OPEN_BURST_BEAT, OPEN_BURST_BEAT + 0.8)));
      const ring = out(seg(b, OPEN_BURST_BEAT, OPEN_BURST_BEAT + 1.1));
      g.save();
