      const grad = g.createRadialGradient(x + dx, y, 0, x + dx, y, rad);
      grad.addColorStop(0, `rgba(200,194,186,${0.08 + r() * 0.1})`);
      grad.addColorStop(1, 'rgba(200,194,186,0)');
      g.fillStyle = grad; g.fillRect(x + dx - rad, y - rad, rad * 2, rad * 2);
    }
