}

// 收尾两页的米白纸面：中心略亮、四周略暗。全片只在这里翻转一次亮暗。
const PAPER = '#F6F3EB', INK = '#070300', PAPER_PAGES = new Set(['ours', 'end']);
function makePaper() {
  const c = canvas();
  const g = c.getContext('2d');
  g.fillStyle = PAPER; g.fillRect(0, 0, W, H);
