function keyed(keys, b) {
  let i = 0;
  while (i + 2 < keys.length && b >= keys[i + 1][0]) i++;
  const [b0, k0] = keys[i], [b1, k1] = keys[i + 1];
  const t = ease(seg(b, b0, b1));
  return k0.map((v, j) => lerp(v, k1[j], t));
}
