    }).filter(q => q.t > 0).sort((p, q) => q.Z - p.Z || Math.abs(q.X) - Math.abs(p.X));
    for (const q of cubes) {
      const face = q === DAI || q.i === DAI.i ? clamp((dv - 0.25) / 0.5) : 0;
      cube3d(g, c, q.X, q.Y, q.Z, CUBE, q.ch, q.key ? 0 : 0.35 * rise, q.key ? rise : 0, face);
