// 用与 main.js 相同的相机公式，算关键立体元素在屏幕上的范围，检查是否在画面内、是否互相重叠。
function cam(x, y, z, pitch, yaw = 0, f = 1100) {
  const cp = Math.cos(pitch), sp = Math.sin(pitch), cy = Math.cos(yaw), sy = Math.sin(yaw);
  return {x, y, z, f, r: [cy, 0, -sy], u: [sp * sy, cp, sp * cy], fw: [cp * sy, -sp, cp * cy]};
}
function orbit(tx, ty, tz, dist, pitch, yaw = 0) {
  const c = cam(0, 0, 0, pitch, yaw);
  return cam(tx - c.fw[0] * dist, ty - c.fw[1] * dist, tz - c.fw[2] * dist, pitch, yaw);
}
const dot = (a, x, y, z) => a[0] * x + a[1] * y + a[2] * z;
function proj(c, X, Y, Z) {
  const dx = X - c.x, dy = Y - c.y, dz = Z - c.z, z = dot(c.fw, dx, dy, dz);
  return {x: Math.round(960 + c.f * dot(c.r, dx, dy, dz) / z), y: Math.round(540 - c.f * dot(c.u, dx, dy, dz) / z), z: Math.round(z)};
}
const ease = x => (x < 0.5 ? 4 * x ** 3 : 1 - (-2 * x + 2) ** 3 / 2);
const lerp = (a, b, t) => a + (b - a) * t;
const seg = (b, b0, b1) => Math.max(0, Math.min(1, (b - b0) / (b1 - b0)));
const KEYS = [[0, [0, 380, 0, 0.06]], [1, [0, 380, 0, 0.06]], [3, [0, 2000, 1150, 0.93]], [6.6, [0, 1850, 1300, 0.95]], [8, [0, 620, 250, 0.02]], [10, [0, 620, 420, 0.02]], [16, [0, 620, 420, 0.02]]];
function openCam(b) {
  let i = 0; while (i + 2 < KEYS.length && b >= KEYS[i + 1][0]) i++;
  const t = ease(seg(b, KEYS[i][0], KEYS[i + 1][0]));
  return cam(...KEYS[i][1].map((v, j) => lerp(v, KEYS[i + 1][1][j], t)));
}
const box = pts => [Math.min(...pts.map(p => p.x)), Math.min(...pts.map(p => p.y)), Math.max(...pts.map(p => p.x)), Math.max(...pts.map(p => p.y))];
const out = {};
// 开场：墨滴第 0 帧、落点；八个字平躺（第 3、6.5 拍）与立定（第 8、10 拍）时贴图四角
out.drop0 = proj(openCam(0), 0, 1250, 2700);
out.impact = proj(openCam(0), 0, 0, 2700);
for (const [b, phi] of [[3, 0], [6.5, 0], [8, Math.PI / 2], [10, Math.PI / 2]]) {
  const c = openCam(b), s = Math.sin(phi), co = Math.cos(phi);
  const O = [-1100, 1240 * s, 2080 + 1240 * co], V = [0, -s, -co];
  out[`glyphs b${b}`] = box([[0, 0], [2200, 0], [0, 1240], [2200, 1240]].map(([u, v]) => proj(c, O[0] + u, O[1] + V[1] * v, O[2] + V[2] * v)));
}
// 第 2 页方块（第 10 拍相机）
{
  const c = cam(0, 1000, 300 + 140 * (10 / 13.4), 0.38);
  for (const [name, X, Z] of [['国', -520, 3200], ['事', 290, 3200], ['千', -520, 2200], ['力', 290, 2200]]) {
    const pts = [[X, 0, Z], [X + 240, 0, Z], [X, 240, Z], [X + 240, 240, Z], [X, 240, Z + 240], [X + 240, 240, Z + 240]].map(p => proj(c, ...p));
    out[`cube ${name}`] = box(pts);
  }
}
// 第 7 页地图：两城锚点与球堆（相机首尾两个偏航）
for (const b of [0, 12]) {
  const c = orbit(0, 0, 150, 3000, 0.5, lerp(-0.12, 0.1, ease(seg(b, 0, 12))));
  out[`aid b${b} 成都`] = proj(c, -1500, 0, 900);
  out[`aid b${b} 杭州`] = proj(c, 1300, 0, 1100);
  out[`aid b${b} 弧顶`] = proj(c, 0, 850, 1000);
  out[`aid b${b} 球堆`] = box([[1300 - 6 * 94, 46, -300], [1300 + 6 * 94, 46, -300], [1300, 46 + 6 * 80, -300]].map(p => proj(c, ...p)));
}
// 第 9 页“大”（静止相机）
{
  const c = orbit(900 * 0.55, 0, 0, 3500, 1.12);
  out['creed 大'] = box([[900 - 945, -945], [900 + 945, -945], [900 - 945, 945], [900 + 945, 945]].map(([x, z]) => proj(c, x, 0, z)));
}
// 第 11 页无人机起飞区
{
  const c = cam(0, 260, 0, 0.06);
  out['drones 起飞区'] = box([[-1700, 0, 1500], [1900, 0, 1500], [-1700, 0, 3700], [1900, 0, 3700]].map(p => proj(c, ...p)));
  out['drones 地平线 y'] = Math.round(540 - 1100 * Math.tan(0.06));
}
for (const [k, v] of Object.entries(out)) console.log(k.padEnd(18), JSON.stringify(v));

